INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (1426,0,1,'Гр-р-р-р... Свежее мясо!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Гр-р-р-р... Свежее мясо!',`text_loc8`);
