INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (1443,0,0,'Сим я разрушаю эти орудия зла! Во славу Орды!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Сим я разрушаю эти орудия зла! Во славу Орды!',`text_loc8`);
