INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (1494,0,0,'Ммм, ПАХНЕТ ЕДОЙ!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ммм, ПАХНЕТ ЕДОЙ!',`text_loc8`);
