INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (2917,7,0,'%s осматривает древний замшелый камень.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s осматривает древний замшелый камень.',`text_loc8`);
