INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (2917,11,0,'%s возвращается к работе, позабыв обо всем окружающем.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s возвращается к работе, позабыв обо всем окружающем.',`text_loc8`);
