INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (3218,0,1,'Прошу вас, скажите мне, что вы не делали того, о чем я думаю. Я очень не хочу делать вам больно...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Прошу вас, скажите мне, что вы не делали того, о чем я думаю. Я очень не хочу делать вам больно...',`text_loc8`);
