INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (3218,0,2,'Нам что, без тебя проблем не хватает?!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нам что, без тебя проблем не хватает?!',`text_loc8`);
