INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (6729,1,0,'Поговорите со мной. Я расскажу вам свою историю.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Поговорите со мной. Я расскажу вам свою историю.',`text_loc8`);
