INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9623,2,0,'Хорошо... хорошо, Чи-Та. Чи-Та хорошо... Дом. Ищи дом.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Хорошо... хорошо, Чи-Та. Чи-Та хорошо... Дом. Ищи дом.',`text_loc8`);
