INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9816,0,0,'%s начинает восстанавливать прежнюю силу!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s начинает восстанавливать прежнюю силу!',`text_loc8`);
