INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9816,1,0,'Еще немного, и %s наберет силу!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Еще немного, и %s наберет силу!',`text_loc8`);
