INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9816,2,0,'%s восстанавливает силы и рвет путы!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s восстанавливает силы и рвет путы!',`text_loc8`);
