INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9816,3,0,'Ха! Ха! Ха! Спасибо, что освободили меня, глупцы. А теперь я отблагодарю вас, содрав мясо с ваших костей.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ха! Ха! Ха! Спасибо, что освободили меня, глупцы. А теперь я отблагодарю вас, содрав мясо с ваших костей.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9999,0,0,'Хм, не уверен, что смогу продержаться долго... Я чувствую ужасную слабость...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Хм, не уверен, что смогу продержаться долго... Я чувствую ужасную слабость...',`text_loc8`);
