INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (9999,2,1,'Теперь мне получше, спасибо.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Теперь мне получше, спасибо.',`text_loc8`);
