INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (10162,8,0,'Вождь не будет с вами церемониться, смертные. Готовьтесь!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Вождь не будет с вами церемониться, смертные. Готовьтесь!',`text_loc8`);
