INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (10162,10,0,'Наслаждайтесь победой, пока можете. Дни Альянса и Орды сочтены! Наша следующая встреча может стать последней.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Наслаждайтесь победой, пока можете. Дни Альянса и Орды сочтены! Наша следующая встреча может стать последней.',`text_loc8`);
