INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (10162,11,0,'Смертные побеждены! Грядет новая эра Легиона Черной горы!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Смертные побеждены! Грядет новая эра Легиона Черной горы!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (10162,12,0,'В этом мире, где время – ваш враг, оно – мой величайший союзник. Это великая игра под названием "жизнь", в которую, как вы думаете, вы играете, на самом деле играет вами. К нему я обращаюсь...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','В этом мире, где время – ваш враг, оно – мой величайший союзник. Это великая игра под названием "жизнь", в которую, как вы думаете, вы играете, на самом деле играет вами. К нему я обращаюсь...',`text_loc8`);
