INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (10181,0,0,'Глупцы. Обсидион! Восстань и уничтожь чужаков!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Глупцы. Обсидион! Восстань и уничтожь чужаков!',`text_loc8`);
