INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (10220,0,0,'%s, падая, исторгает утробный рык. Пугающий вой эхом отдается в залах Пика Черной горы. Кто-то очень, очень сильно разозлился.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s, падая, исторгает утробный рык. Пугающий вой эхом отдается в залах Пика Черной горы. Кто-то очень, очень сильно разозлился.',`text_loc8`);
