INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (12920,0,2,'Нежные, нежные объятия... заберите меня...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нежные, нежные объятия... заберите меня...',`text_loc8`);
