INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14224,0,0,'Обнаружены неизвестные формы жизни... Оцениваю ситуацию...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Обнаружены неизвестные формы жизни... Оцениваю ситуацию...',`text_loc8`);
