INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14224,0,1,'Цель потеряна... Возобновляю поиск по схеме "Дельта".') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Цель потеряна... Возобновляю поиск по схеме "Дельта".',`text_loc8`);
