INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14224,0,2,'Сканирую формы жизни... Цель не найдена.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Сканирую формы жизни... Цель не найдена.',`text_loc8`);
