INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14267,0,1,'Моя бить! Твоя умирать!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Моя бить! Твоя умирать!',`text_loc8`);
