INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14509,0,0,'Ширвалла, наполни меня своим ГНЕВОМ!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ширвалла, наполни меня своим ГНЕВОМ!',`text_loc8`);
