INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14822,0,0,'Придите ко мне и узнайте, что вам готовит будущее!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Придите ко мне и узнайте, что вам готовит будущее!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14822,0,1,'Поговорите со мной, и все, что доселе было скрыто в тумане, станет кристально ясным!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Поговорите со мной, и все, что доселе было скрыто в тумане, станет кристально ясным!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14822,0,2,'Не бойтесь! Тем, кто знает свой путь, судьба известна наперед.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не бойтесь! Тем, кто знает свой путь, судьба известна наперед.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14822,0,3,'Чем дольше вы тянете, тем короче будущее, которое я могу предсказать!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Чем дольше вы тянете, тем короче будущее, которое я могу предсказать!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,0,3,'Добро пожаловать все и каждый на величайшее шоу во всем Азероте... ярмарку Новолуния! Приключения и развлечения ждут вас, не стесняйтесь! Загадки и призы для детей и взрослых! И обязательно поговорите с профессором о любых картах Новолуния, которые вы можете найти во время своих путешествий!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Добро пожаловать все и каждый на величайшее шоу во всем Азероте... ярмарку Новолуния! Приключения и развлечения ждут вас, не стесняйтесь! Загадки и призы для детей и взрослых! И обязательно поговорите с профессором о любых картах Новолуния, которые вы можете найти во время своих путешествий!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,0,4,'Приветствую вас, друзья! Добро пожаловать на лучшее представление Азерота! $B$BПожалуйста, проходите и наслаждайтесь праздником! К вашим услугам многочисленные аттракционы, захватывающие зрелища и многое другое. Ярмарка Новолуния откроет вам чудеса света! Мы не считаемся с расходами, лишь бы каждый посетитель нашел себе что-то по душе!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Приветствую вас, друзья! Добро пожаловать на лучшее представление Азерота! $B$BПожалуйста, проходите и наслаждайтесь праздником! К вашим услугам многочисленные аттракционы, захватывающие зрелища и многое другое. Ярмарка Новолуния откроет вам чудеса света! Мы не считаемся с расходами, лишь бы каждый посетитель нашел себе что-то по душе!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,0,5,'Приходите, приходите все! Добро пожаловать на ярмарку Новолуния! Ищете приключений? Экзотических и мистических сокровищ? Довольно поисков! Вы обратились по адресу! Заходите и примите участие во всем, что может предложить наша ярмарка! Мы будем здесь всю неделю, так что обязательно расскажите о нас своим друзьям и любимым!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Приходите, приходите все! Добро пожаловать на ярмарку Новолуния! Ищете приключений? Экзотических и мистических сокровищ? Довольно поисков! Вы обратились по адресу! Заходите и примите участие во всем, что может предложить наша ярмарка! Мы будем здесь всю неделю, так что обязательно расскажите о нас своим друзьям и любимым!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,0,6,'Мы вернулись и стали еще лучше! Это ярмарка Новолуния, и вам несказанно повезло! Здесь собраны разные чудеса и диковинки со всего мира. Неважно, молоды вы или стары, богаты или бедны – на ярмарке Новолуния рады всем! Обменивайте призовые купоны у Гелваса Углешлюза на удивительные экзотические подарки!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мы вернулись и стали еще лучше! Это ярмарка Новолуния, и вам несказанно повезло! Здесь собраны разные чудеса и диковинки со всего мира. Неважно, молоды вы или стары, богаты или бедны – на ярмарке Новолуния рады всем! Обменивайте призовые купоны у Гелваса Углешлюза на удивительные экзотические подарки!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,0,'Заходите, заходите все. Добро пожаловать на ярмарку Новолуния! Не стесняйтесь. Заходите, к Лахре, и купите себе экзотический артефакт из далеких земель. Если вам повезло найти карты Новолуния, поговорите с профессором Палео. Голодны? Испытываете жажду? Вам повезло! У Силаннии и Топа продаются превосходные закуски и напитки! Я бы рекомендовал "Особое Новолунное", чтобы смыть немного перца с крылышек. И если вы мечтаете узнать о будущем, бегите бегом к Воржею...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Заходите, заходите все. Добро пожаловать на ярмарку Новолуния! Не стесняйтесь. Заходите, к Лахре, и купите себе экзотический артефакт из далеких земель. Если вам повезло найти карты Новолуния, поговорите с профессором Палео. Голодны? Испытываете жажду? Вам повезло! У Силаннии и Топа продаются превосходные закуски и напитки! Я бы рекомендовал "Особое Новолунное", чтобы смыть немного перца с крылышек. И если вы мечтаете узнать о будущем, бегите бегом к Воржею...',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,1,'Приходите, приходите все! Добро пожаловать на ярмарку Новолуния! Ищете приключений? Экзотических и мистических сокровищ? Довольно поисков! Вы обратились по адресу! Заходите и примите участие во всем, что может предложить наша ярмарка! Мы будем здесь всю неделю, так что обязательно расскажите о нас своим друзьям и любимым!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Приходите, приходите все! Добро пожаловать на ярмарку Новолуния! Ищете приключений? Экзотических и мистических сокровищ? Довольно поисков! Вы обратились по адресу! Заходите и примите участие во всем, что может предложить наша ярмарка! Мы будем здесь всю неделю, так что обязательно расскажите о нас своим друзьям и любимым!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,2,'Мы вернулись и стали еще лучше! Это ярмарка Новолуния, и вам несказанно повезло! Здесь собраны разные чудеса и диковинки со всего мира. Неважно, молоды вы или стары, богаты или бедны – на ярмарке Новолуния рады всем! Обменивайте призовые купоны у Гелваса Углешлюза на удивительные экзотические подарки!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мы вернулись и стали еще лучше! Это ярмарка Новолуния, и вам несказанно повезло! Здесь собраны разные чудеса и диковинки со всего мира. Неважно, молоды вы или стары, богаты или бедны – на ярмарке Новолуния рады всем! Обменивайте призовые купоны у Гелваса Углешлюза на удивительные экзотические подарки!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,3,'Добро пожаловать на величайшее представление Азерота – ярмарку Новолуния! Проходите, не стесняйтесь, здесь каждый найдет для себя развлечения и приключения, диковинки и призы! Обязательно покажите профессору все карты Новолуния, которые успели собрать!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Добро пожаловать на величайшее представление Азерота – ярмарку Новолуния! Проходите, не стесняйтесь, здесь каждый найдет для себя развлечения и приключения, диковинки и призы! Обязательно покажите профессору все карты Новолуния, которые успели собрать!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,4,'Здравствуйте, друзья! Добро пожаловать на величайшее представление Азерота!$b$bПожалуйста, проходите и посмотрите, что мы предлагаем посетителям! Взгляните на диковинки, которые ярмарка Новолуния собрала по всему широкому и удивительному миру! Мы устроили здесь восхитительный парк развлечений для детей от 7 до 70!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Здравствуйте, друзья! Добро пожаловать на величайшее представление Азерота!$b$bПожалуйста, проходите и посмотрите, что мы предлагаем посетителям! Взгляните на диковинки, которые ярмарка Новолуния собрала по всему широкому и удивительному миру! Мы устроили здесь восхитительный парк развлечений для детей от 7 до 70!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,5,'У всех все хорошо? Вот и славно! Добро пожаловать на ярмарку Новолуния, самое веселое мероприятие в Запределье! Обязательно поговорите с Эбби и его друзьями, когда посетите чудной зоопарк Эбба Ниблгира.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','У всех все хорошо? Вот и славно! Добро пожаловать на ярмарку Новолуния, самое веселое мероприятие в Запределье! Обязательно поговорите с Эбби и его друзьями, когда посетите чудной зоопарк Эбба Ниблгира.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14823,1,6,'Приветствую всех на ярмарке Новолуния, величайшем событии всех миров! У нас есть все: вкусная еда, крепкая выпивка, экзотические артефакты, гадалки, потрясающие призы и бесконечные развлечения! Не забудьте предъявить призовые купоны ярмарки Новолуния Гелвасу Углешлюзу! За пять или больше количество купонов вы получите самые лучшие подарки в Запределье. Проигравших не будет!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Приветствую всех на ярмарке Новолуния, величайшем событии всех миров! У нас есть все: вкусная еда, крепкая выпивка, экзотические артефакты, гадалки, потрясающие призы и бесконечные развлечения! Не забудьте предъявить призовые купоны ярмарки Новолуния Гелвасу Углешлюзу! За пять или больше количество купонов вы получите самые лучшие подарки в Запределье. Проигравших не будет!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14828,0,0,'Пять купонов или пятьсот – без разницы, дружище! Выигрывает каждый!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Пять купонов или пятьсот – без разницы, дружище! Выигрывает каждый!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14828,0,1,'Искателей приключений ждут таинственные призы! Подходите, подходите!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Искателей приключений ждут таинственные призы! Подходите, подходите!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14828,0,2,'Подарки! Подарки! Меняйте подарочные купоны ярмарки на ценные подарки!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Подарки! Подарки! Меняйте подарочные купоны ярмарки на ценные подарки!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14828,0,3,'Купоны! Меняйте подарочные купоны на чудесные, диковинные призы!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Купоны! Меняйте подарочные купоны на чудесные, диковинные призы!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14834,1,0,'Бегство не спасет вас, смертные!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Бегство не спасет вас, смертные!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14834,3,0,'Слуги Хаккара, внемлите своему богу. Храм под угрозой. Неверные вторглись в священные земли. Защищайте Алтарь Крови! Убейте их всех!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Слуги Хаккара, внемлите своему богу. Храм под угрозой. Неверные вторглись в священные земли. Защищайте Алтарь Крови! Убейте их всех!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,0,0,'Подходите, покажите, на что вы способны!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Подходите, покажите, на что вы способны!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,0,1,'Стреляй – призы получай! Призы за меткость!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Стреляй – призы получай! Призы за меткость!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,1,0,'Ружья, карабины, пистолеты! Ну же, дружище!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ружья, карабины, пистолеты! Ну же, дружище!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,1,1,'Эй, ребята, кому редкостей и диковинок – бесплатно?! Не пропустите!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Эй, ребята, кому редкостей и диковинок – бесплатно?! Не пропустите!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,1,2,'Умеешь стрелять? У тебя все шансы получить замечательные призы!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Умеешь стрелять? У тебя все шансы получить замечательные призы!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,1,3,'Эта игра настолько проста, что даже |3-6($c) имеет все шансы на победу!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Эта игра настолько проста, что даже |3-6($c) имеет все шансы на победу!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,1,4,'Меткость! Проверь свою меткость!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Меткость! Проверь свою меткость!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14841,1,5,'Испытай себя – ну и выиграй приз заодно!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Испытай себя – ну и выиграй приз заодно!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14847,0,0,'Колоды Новолуния! Сдавайте их сюда!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Колоды Новолуния! Сдавайте их сюда!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14847,0,1,'Поговори со мной, если у тебя есть карты Новолуния.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Поговори со мной, если у тебя есть карты Новолуния.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14847,0,2,'А у тебя есть карты с ярмарки Новолуния? Если не боишься – поговори со мной, много интересного о них узнаешь!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','А у тебя есть карты с ярмарки Новолуния? Если не боишься – поговори со мной, много интересного о них узнаешь!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14860,0,1,'Она убегает!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Она убегает!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14860,0,2,'А ну назад!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','А ну назад!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (14860,0,3,'Покупайте лягушек и кожаные мячики!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Покупайте лягушек и кожаные мячики!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15184,0,0,'Отведай моего клинка, пес!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Отведай моего клинка, пес!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15184,0,1,'Прошу вас, скажите мне, что вы не делали того, о чем я думаю. Я очень не хочу делать вам больно...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Прошу вас, скажите мне, что вы не делали того, о чем я думаю. Я очень не хочу делать вам больно...',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15184,0,2,'Нам что, без тебя проблем не хватает?!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нам что, без тебя проблем не хватает?!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15263,0,0,'Хотите умереть? С удовольствием помогу вам в этом!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Хотите умереть? С удовольствием помогу вам в этом!',`text_loc8`);
