INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15263,3,0,'Вы лишь откладываете неизбежное!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Вы лишь откладываете неизбежное!',`text_loc8`);
