INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15303,0,0,'Не волнуйся, |3-6($c), лишний вес – не беда, эта пушка осилит любой груз!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не волнуйся, |3-6($c), лишний вес – не беда, эта пушка осилит любой груз!',`text_loc8`);
