INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15303,1,0,'Кто хочет попробовать себя в роли пушечного ядра? Незабываемые ощущения!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Кто хочет попробовать себя в роли пушечного ядра? Незабываемые ощущения!',`text_loc8`);
