INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15339,2,0,'Взвейтесь, пески пустыни, и закройте солнце!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Взвейтесь, пески пустыни, и закройте солнце!',`text_loc8`);
