INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15956,0,2,'Бегите, бегите! Я люблю горячую кровь!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Бегите, бегите! Я люблю горячую кровь!',`text_loc8`);
