INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15956,1,0,'О, добро пожаловать в мою гостиную.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','О, добро пожаловать в мою гостиную.',`text_loc8`);
