INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15956,1,1,'Я слышу биение маленьких сердец. Да... теперь они бьются быстрее... Но скоро они остановятся.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я слышу биение маленьких сердец. Да... теперь они бьются быстрее... Но скоро они остановятся.',`text_loc8`);
