INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15956,1,2,'Куда идти? Что делать? Выбирайте, но все пути ведут к боли... и смерти.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Куда идти? Что делать? Выбирайте, но все пути ведут к боли... и смерти.',`text_loc8`);
