INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15956,1,3,'Кого мне съесть первым? Сложный выбор... Все они пахнут так вкусно...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Кого мне съесть первым? Сложный выбор... Все они пахнут так вкусно...',`text_loc8`);
