INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (15956,1,4,'Подойдите ближе. Лакомые кусочки. Я слишком долго мечтал о еде. И крови.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Подойдите ближе. Лакомые кусочки. Я слишком долго мечтал о еде. И крови.',`text_loc8`);
