INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (16807,4,1,'Давайте, покажите мне, на что вы способны!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Давайте, покажите мне, на что вы способны!',`text_loc8`);
