INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (17377,2,0,'Только этого ты и заслуживаешь!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Только этого ты и заслуживаешь!',`text_loc8`);
