INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (17391,1,0,'[Фурболг] Ритк кин\'чиккс азул лазурная вершина...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','[Фурболг] Ритк кин\'чиккс азул лазурная вершина...',`text_loc8`);
