INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (18096,0,0,'Тралл! Выйди – и встреть свою судьбу!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Тралл! Выйди – и встреть свою судьбу!',`text_loc8`);
