INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (18096,0,1,'Жизнь Тареты висит на волоске. Разумеется, она тебе небезразлична. Разумеется, ты хочешь ее спасти.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Жизнь Тареты висит на волоске. Разумеется, она тебе небезразлична. Разумеется, ты хочешь ее спасти.',`text_loc8`);
