INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (18096,1,1,'С судьбой бороться бесполезно!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','С судьбой бороться бесполезно!',`text_loc8`);
