INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (18096,2,1,'Тралл останется рабом, а Тарета умрет!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Тралл останется рабом, а Тарета умрет!',`text_loc8`);
