INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (18371,0,0,'$n оказывается в зоне внимания |3-1(%s).') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','$n оказывается в зоне внимания |3-1(%s).',`text_loc8`);
