INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (18588,0,0,'Я выбираю третий вариант: УБИТЬ ТЕБЯ!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я выбираю третий вариант: УБИТЬ ТЕБЯ!',`text_loc8`);
