INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (19216,13,0,'Там, где нет света, процветают отчаяние, ненависть и гнев.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Там, где нет света, процветают отчаяние, ненависть и гнев.',`text_loc8`);
