INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (20912,5,0,'Мы бесчисленны, как звезды! Мы заполоним вселенную!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мы бесчисленны, как звезды! Мы заполоним вселенную!',`text_loc8`);
