INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (20912,6,0,'Я всего лишь один... из бесконечного множества.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я всего лишь один... из бесконечного множества.',`text_loc8`);
