INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (21213,0,0,'Да поглотит вас пучина вод!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Да поглотит вас пучина вод!',`text_loc8`);
