INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (23995,0,0,'Мне казалось, мы все уже обсудили, Брогг. Тебе нельзя здесь оставаться. Да, ты тут помещаешься, но больше-то никому места нет!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мне казалось, мы все уже обсудили, Брогг. Тебе нельзя здесь оставаться. Да, ты тут помещаешься, но больше-то никому места нет!',`text_loc8`);
