INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (23995,1,0,'Ну да, сказали, но ведь это наш штаб! Здесь все наши инструкции и чертежи хранятся!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ну да, сказали, но ведь это наш штаб! Здесь все наши инструкции и чертежи хранятся!',`text_loc8`);
