INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25144,0,1,'Приглядывай за демонами. Пока что Плеть нас не интересует.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Приглядывай за демонами. Пока что Плеть нас не интересует.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,2,0,'Я встречался с дренеями раньше, в Скеттисе, а потом еще в Долине Призрачной Луны. Но здесь, в Азероте, положение дел куда хуже.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я встречался с дренеями раньше, в Скеттисе, а потом еще в Долине Призрачной Луны. Но здесь, в Азероте, положение дел куда хуже.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,3,0,'Во-первых, син\'дорай, слушайте хорошенько. У нас строгие порядки... не то, к чему вы привыкли у Провидцев. Работайте как следует, или убирайтесь восвояси!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Во-первых, син\'дорай, слушайте хорошенько. У нас строгие порядки... не то, к чему вы привыкли у Провидцев. Работайте как следует, или убирайтесь восвояси!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,4,0,'Ну что же – с главными вопросами мы разобрались. Добро пожаловать на остров Кель\'Данас! Солнечный Колодец расположен на плоскогорье к югу отсюда, а принц Кель\'тас спрятался в Террасе Магистров на востоке.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ну что же – с главными вопросами мы разобрались. Добро пожаловать на остров Кель\'Данас! Солнечный Колодец расположен на плоскогорье к югу отсюда, а принц Кель\'тас спрятался в Террасе Магистров на востоке.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,8,0,'Добро пожаловать в Солнечный Колодец. Несмотря на мягкий климат и живописные виды, отдыхать вам не придется, дамы и господа!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Добро пожаловать в Солнечный Колодец. Несмотря на мягкий климат и живописные виды, отдыхать вам не придется, дамы и господа!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,9,0,'На данный момент дела обстоят так: мы удерживаем то, что можем, а те, у кого больше опыта и лучше снаряжение, выступают против принца Кель\'таса.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','На данный момент дела обстоят так: мы удерживаем то, что можем, а те, у кого больше опыта и лучше снаряжение, выступают против принца Кель\'таса.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,12,0,'Воинов разместят на тактически важных позициях, а стрелкам будет поручено не подпускать сюда вражеских воздушных наездников.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Воинов разместят на тактически важных позициях, а стрелкам будет поручено не подпускать сюда вражеских воздушных наездников.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,13,0,'Я жду приказа касательно вашего особого задания. А пока что оставайтесь здесь и будьте готовы выступить по первому требованию!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я жду приказа касательно вашего особого задания. А пока что оставайтесь здесь и будьте готовы выступить по первому требованию!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,15,0,'Новобранцы, смирно! Я – сержант-инструктор Бадум. Ближайшие несколько дней я буду проводить у вас инструктаж.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Новобранцы, смирно! Я – сержант-инструктор Бадум. Ближайшие несколько дней я буду проводить у вас инструктаж.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,16,0,'Остров Кель\'Данас был захвачен войсками принца Кель\'таса Солнечного Скитальца. Разведка считала его погибшим. Разведка ошиблась.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Остров Кель\'Данас был захвачен войсками принца Кель\'таса Солнечного Скитальца. Разведка считала его погибшим. Разведка ошиблась.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,19,0,'Нетрудно понять, что многие из нас не вернутся домой. Но если не забывать, чему вас учили, и не паниковать, ваши шансы значительно возрастут.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нетрудно понять, что многие из нас не вернутся домой. Но если не забывать, чему вас учили, и не паниковать, ваши шансы значительно возрастут.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25162,20,0,'На данный момент это все, что я хотел сказать. Не расслабляться, мальчики и девочки.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','На данный момент это все, что я хотел сказать. Не расслабляться, мальчики и девочки.',`text_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25165,0,0,'Ты расскажешь мне, что с ними случилось!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты расскажешь мне, что с ними случилось!',`text_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text
