INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25208,2,0,'Этого вполне достаточно. Дальше я сам доберусь.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Этого вполне достаточно. Дальше я сам доберусь.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25208,3,0,'Благодарю за спасение. Пожалуйста, передай королю, что я вернулся.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Благодарю за спасение. Пожалуйста, передай королю, что я вернулся.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25248,0,0,'Ну...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ну...',`text_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25315,0,0,'Я отдал все, что мог. Моя энергия в ваших руках!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я отдал все, что мог. Моя энергия в ваших руках!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25315,5,0,'Никто не остановит меня! Этот мир падет!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Никто не остановит меня! Этот мир падет!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25319,2,0,'Я наполнил энергией еще одну сферу! Быстрее используйте ее!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я наполнил энергией еще одну сферу! Быстрее используйте ее!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25319,3,0,'Готова еще одна сфера! Торопитесь!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Готова еще одна сфера! Торопитесь!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25319,4,0,'Я отдал все, что мог. Моя энергия в ваших руках!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я отдал все, что мог. Моя энергия в ваших руках!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25478,2,0,'Ааааа! Отпусти меня! Я тебе не нужен! Клянусь!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ааааа! Отпусти меня! Я тебе не нужен! Клянусь!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25478,6,0,'Неееееет! Это нечеловеческая пытка! Ты заполучил то, что хотел... почему ты меня просто не убьешь?') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Неееееет! Это нечеловеческая пытка! Ты заполучил то, что хотел... почему ты меня просто не убьешь?',`text_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text
