INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (25832,0,0,'Я – вестник Механозода. Да спадет с вас проклятье!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я – вестник Механозода. Да спадет с вас проклятье!',`text_loc8`);
