INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (27629,0,0,'$gГотов:Готова; к бою, |3-6($c)?') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','$gГотов:Готова; к бою, |3-6($c)?',`text_loc8`);
