INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (27629,1,6,'Молодец, что $gзаметил:заметила; этого!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Молодец, что $gзаметил:заметила; этого!',`text_loc8`);
