INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (27654,3,3,'Я приговариваю тебя к смерти!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я приговариваю тебя к смерти!',`text_loc8`);
