INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (27851,0,0,'Стены пещеры Ледяной Скорби дрожат и сотрясаются.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Стены пещеры Ледяной Скорби дрожат и сотрясаются.',`text_loc8`);
