INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (27923,1,0,'Аррр! Мы на месте, дружище! Это Лагерь Скалаваг!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Аррр! Мы на месте, дружище! Это Лагерь Скалаваг!',`text_loc8`);
