INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (27959,0,0,'Думаешь, ты можешь изгнать меня с помощью медитации?') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Думаешь, ты можешь изгнать меня с помощью медитации?',`text_loc8`);
