INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28016,1,0,'Дракуру смотрит вниз, на крепость Драк\'Тарон.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Дракуру смотрит вниз, на крепость Драк\'Тарон.',`text_loc8`);
