INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28016,4,0,'За ваши старания вас ждет величайшая из наград...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','За ваши старания вас ждет величайшая из наград...',`text_loc8`);
