INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28041,0,1,'Будь осторожнее. Эти драккари – мерзкие существа.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Будь осторожнее. Эти драккари – мерзкие существа.',`text_loc8`);
