INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28496,0,0,'Ха! Вам не получить мое сокровище!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ха! Вам не получить мое сокровище!',`text_loc8`);
