INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28498,0,0,'Ты правильно поступил, Дракуру.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты правильно поступил, Дракуру.',`text_loc8`);
