INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28498,1,0,'Твое предательство империи Драккари подарило мне новую армию.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Твое предательство империи Драккари подарило мне новую армию.',`text_loc8`);
