INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28498,4,0,'Теперь ты отвечаешь за очищение Зул\'Драка, Дракуру.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Теперь ты отвечаешь за очищение Зул\'Драка, Дракуру.',`text_loc8`);
