INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28498,5,0,'Не справишься – и я погублю тебя.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не справишься – и я погублю тебя.',`text_loc8`);
