INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28498,6,0,'Преуспеешь – и получишь еще больше силы.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Преуспеешь – и получишь еще больше силы.',`text_loc8`);
