INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28511,0,0,'Око Акеруса устремляется к цели.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Око Акеруса устремляется к цели.',`text_loc8`);
