INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28557,0,4,'Не делай этого! Никто не заслуживает смерти!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не делай этого! Никто не заслуживает смерти!',`text_loc8`);
