INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28563,0,0,'Парящая конструкция начинает вибрировать.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Парящая конструкция начинает вибрировать.',`text_loc8`);
