INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28575,0,1,'Если Рунок вернет свою силу, мы все умрем!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Если Рунок вернет свою силу, мы все умрем!',`text_loc8`);
