INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28575,0,4,'Не дайте ему окрепнуть!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не дайте ему окрепнуть!',`text_loc8`);
