INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28609,0,2,'Ты нежеланный гость в этих землях, чудовище!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты нежеланный гость в этих землях, чудовище!',`text_loc8`);
