INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (28610,6,0,'ЛОЖЬ! О боли, которую тебе предстоит перенести, будут говорить годами!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','ЛОЖЬ! О боли, которую тебе предстоит перенести, будут говорить годами!',`text_loc8`);
