INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29175,29,0,'То, что ты чувствуешь сейчас – это муки тысячи загубленных душ! Душ, которые ты и твой господин завлекли сюда. Свет воздаст тебе по заслугам, Дарион!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','То, что ты чувствуешь сейчас – это муки тысячи загубленных душ! Душ, которые ты и твой господин завлекли сюда. Свет воздаст тебе по заслугам, Дарион!',`text_loc8`);
