INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29175,46,0,'Ты гнусное чудовище, Артас!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты гнусное чудовище, Артас!',`text_loc8`);
