INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29175,59,0,'Поднимись, Дарион, и слушай.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Поднимись, Дарион, и слушай.',`text_loc8`);
