INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29175,61,0,'О таких подвигах никогда нельзя забывать, мы должны ревностно оберегать наши идеалы.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','О таких подвигах никогда нельзя забывать, мы должны ревностно оберегать наши идеалы.',`text_loc8`);
