INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29175,64,0,'Серебряный Рассвет и Серебряная Длань объединятся! Мы преуспеем там, где прежде все терпели неудачу!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Серебряный Рассвет и Серебряная Длань объединятся! Мы преуспеем там, где прежде все терпели неудачу!',`text_loc8`);
