INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29175,66,0,'Серебряный Авангард идет за тобой, Артас!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Серебряный Авангард идет за тобой, Артас!',`text_loc8`);
