INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29178,7,0,'Готовьтесь, братья и сестры! За Свет!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Готовьтесь, братья и сестры! За Свет!',`text_loc8`);
