INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29183,47,0,'Ты прав, Фордринг. Я действительно послал их на верную смерть. Их жизни ничего не стоят, но вот твоя...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты прав, Фордринг. Я действительно послал их на верную смерть. Их жизни ничего не стоят, но вот твоя...',`text_loc8`);
