INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29183,50,0,'КОНЕЦ СВЕТА!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','КОНЕЦ СВЕТА!',`text_loc8`);
