INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29228,37,0,'Отец, я хочу сражаться вместе с тобой против нежити. Я жажду битв! Я не могу больше оставаться безучастным!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Отец, я хочу сражаться вместе с тобой против нежити. Я жажду битв! Я не могу больше оставаться безучастным!',`text_loc8`);
