INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29309,0,0,'Секреты глубин должны остаться секретами.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Секреты глубин должны остаться секретами.',`text_loc8`);
