INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29309,1,2,'Возможно, мы скоро станем друзьями.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Возможно, мы скоро станем друзьями.',`text_loc8`);
