INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29309,3,1,'Шшшад ак кирииииишшш щакк-к-к!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Шшшад ак кирииииишшш щакк-к-к!',`text_loc8`);
