INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29309,4,0,'Ан\'кахарский страж откладывает яйца!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ан\'кахарский страж откладывает яйца!',`text_loc8`);
