INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29311,0,0,'Шгла\'йос праф мх\'наус.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Шгла\'йос праф мх\'наус.',`text_loc8`);
