INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29311,0,1,'Те, что питаются потерянными душами, никогда не утолят свой голод.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Те, что питаются потерянными душами, никогда не утолят свой голод.',`text_loc8`);
