INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29311,1,1,'Уваг ма фгва\'кул хнакф.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Уваг ма фгва\'кул хнакф.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29311,1,2,'Ивак мак ууу. Ивак мак саагх. Ивак ма шг\'фхн.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ивак мак ууу. Ивак мак саагх. Ивак ма шг\'фхн.',`text_loc8`);
