INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29311,2,1,'На место одного павшего встанут множество других воинов.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','На место одного павшего встанут множество других воинов.',`text_loc8`);
