INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29434,0,0,'Дай мне знать о своей готовности. Я бы предпочел раньше, а не позже... если принять во внимание медленную смерть от яда и прочее.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Дай мне знать о своей готовности. Я бы предпочел раньше, а не позже... если принять во внимание медленную смерть от яда и прочее.',`text_loc8`);
