INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29519,0,0,'Это было твоей ужасной ошибкой, чудовище!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Это было твоей ужасной ошибкой, чудовище!',`text_loc8`);
