INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29519,0,1,'Когда-то я был воином Света... И посмотри, что теперь со мной стало...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Когда-то я был воином Света... И посмотри, что теперь со мной стало...',`text_loc8`);
