INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29519,0,4,'Ты ведь позволишь мне взять оружие и доспехи?') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты ведь позволишь мне взять оружие и доспехи?',`text_loc8`);
