INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29542,0,0,'На этот раз я так быстро не умру!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','На этот раз я так быстро не умру!',`text_loc8`);
