INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (29919,3,0,'Мой ответ? Вот тебе мой ответ, ничтожный посланник!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мой ответ? Вот тебе мой ответ, ничтожный посланник!',`text_loc8`);
