INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (30081,0,0,'Как ты смеешь нападать на МЕНЯ?! Тебе не остановить меня, я все равно докажу, что достоин сражаться рядом с Королем-личом!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Как ты смеешь нападать на МЕНЯ?! Тебе не остановить меня, я все равно докажу, что достоин сражаться рядом с Королем-личом!',`text_loc8`);
