INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (30098,0,6,'Тоскливый эль! Покупайте холодный тоскливый эль!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Тоскливый эль! Покупайте холодный тоскливый эль!',`text_loc8`);
