INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (30098,0,7,'Воздушная кукуруза! Орешки! Эль!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Воздушная кукуруза! Орешки! Эль!',`text_loc8`);
