INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (30124,0,0,'О, привет, $gмаленький:маленькая:r; |3-6($r).') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','О, привет, $gмаленький:маленькая:r; |3-6($r).',`text_loc8`);
