INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (31013,2,0,'Пируйте, дети мои! Наслаждайтесь плотью живых!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Пируйте, дети мои! Наслаждайтесь плотью живых!',`text_loc8`);
