INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (31013,3,0,'Сложите оружие и отдайте свои души!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Сложите оружие и отдайте свои души!',`text_loc8`);
