INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (31108,0,0,'Не дай Орде завладеть угольками, $n. Нельзя допустить, чтобы в следующей битве они получили преимущество!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не дай Орде завладеть угольками, $n. Нельзя допустить, чтобы в следующей битве они получили преимущество!',`text_loc8`);
