INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (31109,0,0,'Уничтожь эти мерзкие боевые машины, $n!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Уничтожь эти мерзкие боевые машины, $n!',`text_loc8`);
