INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (31254,0,1,'Слухи оказались верными! Принц сошел с ума!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Слухи оказались верными! Принц сошел с ума!',`text_loc8`);
