INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,0,'Ты точно знаешь, что мы идем в правильную сторону?') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ты точно знаешь, что мы идем в правильную сторону?',`text_loc8`);
