INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,1,'Никто и не говорил, что любовь – это сплошные нежности.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Никто и не говорил, что любовь – это сплошные нежности.',`text_loc8`);
