INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,3,'Хе-хе-хе! Скоро мы с тобой повеселимся!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Хе-хе-хе! Скоро мы с тобой повеселимся!',`text_loc8`);
