INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,4,'Мои соплеменники хорошо сегодня повеселятся!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мои соплеменники хорошо сегодня повеселятся!',`text_loc8`);
