INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,6,'<принюхивается> Я их чую.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','<принюхивается> Я их чую.',`text_loc8`);
