INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,7,'Нет, нет, что ты. Здесь нет моих троллей...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нет, нет, что ты. Здесь нет моих троллей...',`text_loc8`);
