INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (32663,0,8,'Хорошо, дружище. Скажи мне, когда мы подойдем ближе к моим братьям.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Хорошо, дружище. Скажи мне, когда мы подойдем ближе к моим братьям.',`text_loc8`);
