INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (33048,1,0,'Все. Теперь дух великого животного всегда будет сопровождать тебя на Темных берегах. Надеюсь, с его помощью ты будешь верно служить природе.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Все. Теперь дух великого животного всегда будет сопровождать тебя на Темных берегах. Надеюсь, с его помощью ты будешь верно служить природе.',`text_loc8`);
