INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (33113,1,0,'Изменения в протоколе оценки угрозы. Уровень угрозы текущей цели нулевой. Поиск новой цели.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Изменения в протоколе оценки угрозы. Уровень угрозы текущей цели нулевой. Поиск новой цели.',`text_loc8`);
