INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34564,0,0,'А вот и гости заявились, как и обещал господин.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','А вот и гости заявились, как и обещал господин.',`text_loc8`);
