INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34564,6,0,'%s выпускает рой жуков-трупоедов, чтобы восстановить здоровье!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s выпускает рой жуков-трупоедов, чтобы восстановить здоровье!',`text_loc8`);
