INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34564,7,0,'Ф-лаккх шир!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ф-лаккх шир!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34564,7,1,'Еще одна душа накормит хозяина.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Еще одна душа накормит хозяина.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34564,8,0,'Я подвел тебя, господин...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я подвел тебя, господин...',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34574,0,0,'%s подает вялые признаки жизни при вашем приближении, слабо кивая в знак приветствия.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s подает вялые признаки жизни при вашем приближении, слабо кивая в знак приветствия.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34574,1,0,'После битвы за гору Хиджал многое изменилось для нашего народа.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','После битвы за гору Хиджал многое изменилось для нашего народа.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34574,2,0,'Нордрасил сейчас лишь бледная тень того, каким он был раньше. Его прошлое могущество позволило победить Архимонда и отбросить Пылающий Легион.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нордрасил сейчас лишь бледная тень того, каким он был раньше. Его прошлое могущество позволило победить Архимонда и отбросить Пылающий Легион.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34574,3,0,'Мы лишились бессмертия – самой сущности нашего естества!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мы лишились бессмертия – самой сущности нашего естества!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34574,5,0,'Темные времена для всех.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Темные времена для всех.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34574,6,0,'Калдорайская тень закрывает глаза и исчезает.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Калдорайская тень закрывает глаза и исчезает.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,0,0,'%s отдыхает на краю лунного колодца, предаваясь тихому созерцанию.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s отдыхает на краю лунного колодца, предаваясь тихому созерцанию.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,1,0,'В течение последних недель те, кто живет в верхней части Тельдрассила, заметили, что их воспоминания стали расплывчатыми, как будто время овладело частью их жизней.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','В течение последних недель те, кто живет в верхней части Тельдрассила, заметили, что их воспоминания стали расплывчатыми, как будто время овладело частью их жизней.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,2,0,'Мы выбрались из этого тумана для того, чтобы узнать, что Фэндрал Олений Шлем и многие из его ближайших последователей исчезли, не сказав никому ни слова.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мы выбрались из этого тумана для того, чтобы узнать, что Фэндрал Олений Шлем и многие из его ближайших последователей исчезли, не сказав никому ни слова.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,3,0,'Но в то же время Шан\'до Ярость Бури очнулся от своего сна и возвратился к своей любимой Тиранде Шелест Ветра.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Но в то же время Шан\'до Ярость Бури очнулся от своего сна и возвратился к своей любимой Тиранде Шелест Ветра.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,5,0,'И хотя Тельдрассил еще не полностью избавился от искажений, его ветви уже изменились. Он начал расти заново.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','И хотя Тельдрассил еще не полностью избавился от искажений, его ветви уже изменились. Он начал расти заново.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,6,0,'Никто не знает, чего ждать дальше, но после воссоединения Малфуриона и Тиранды у калдорай снова появилась надежда.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Никто не знает, чего ждать дальше, но после воссоединения Малфуриона и Тиранды у калдорай снова появилась надежда.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,7,0,'Надеюсь, мы избавились от мрака, который так долго омрачал жизнь нашего народа.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Надеюсь, мы избавились от мрака, который так долго омрачал жизнь нашего народа.',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34585,8,0,'Калдорайская тень закрывает глаза и исчезает.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Калдорайская тень закрывает глаза и исчезает.',`text_loc8`);
