INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34715,2,0,'Смотри, куда идешь! Или хочешь разбиться в лепешку? Кстати, добро пожаловать в Громовой Утес!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Смотри, куда идешь! Или хочешь разбиться в лепешку? Кстати, добро пожаловать в Громовой Утес!',`text_loc8`);
