INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34715,3,0,'Ладно, ребята, давайте доставим эту крошку прямо к Оргриммару!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Ладно, ребята, давайте доставим эту крошку прямо к Оргриммару!',`text_loc8`);
