INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34723,0,2,'Летит корабль! Нет, гарпия!.. стоять, это опять птица.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Летит корабль! Нет, гарпия!.. стоять, это опять птица.',`text_loc8`);
