INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34990,0,0,'Твои чудовища не чета героям Альянса, Тирион!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Твои чудовища не чета героям Альянса, Тирион!',`text_loc8`);
