INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (34990,50,0,'Состязания мне не по душе, Тирион. И все же я надеюсь, что они выступят достойно.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Состязания мне не по душе, Тирион. И все же я надеюсь, что они выступят достойно.',`text_loc8`);
