INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35005,2,0,'Серебряный союз с гордостью представляет своих бойцов, верховный лорд.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Серебряный союз с гордостью представляет своих бойцов, верховный лорд.',`text_loc8`);
