INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35005,3,0,'Из ворот появляется Эрессея Певица Рассвета, непобедимый паладин и абсолютный чемпион Луносвета!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Из ворот появляется Эрессея Певица Рассвета, непобедимый паладин и абсолютный чемпион Луносвета!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35005,4,0,'На арену ступает непреклонный и смертоносный Зул\'тор, абсолютный чемпион Сен\'джина!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','На арену ступает непреклонный и смертоносный Зул\'тор, абсолютный чемпион Сен\'джина!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35005,5,0,'Представляем вам абсолютного чемпиона Оргриммара, яростного Мокру Дробителя Черепов!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Представляем вам абсолютного чемпиона Оргриммара, яростного Мокру Дробителя Черепов!',`text_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35005,6,0,'На арену выходит абсолютный чемпион Подгорода, воплощение стойкости Отрекшихся – ловчий смерти Визери!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','На арену выходит абсолютный чемпион Подгорода, воплощение стойкости Отрекшихся – ловчий смерти Визери!',`text_loc8`);
