INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35005,7,0,'Оседлав своего кодо, возвышается перед нами непобедимый Рунок Буйногривый, абсолютный чемпион Громового Утеса!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Оседлав своего кодо, возвышается перед нами непобедимый Рунок Буйногривый, абсолютный чемпион Громового Утеса!',`text_loc8`);
