INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35451,4,0,'Моя дряхлая плоть лишь мешала в бою!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Моя дряхлая плоть лишь мешала в бою!',`text_loc8`);
