INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35451,5,0,'Мне и кости не нужны, чтобы одолеть вас!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мне и кости не нужны, чтобы одолеть вас!',`text_loc8`);
