INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (35451,7,0,'Нет! Я не могу... снова... проиграть.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нет! Я не могу... снова... проиграть.',`text_loc8`);
