INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36494,0,0,'Маленьких букашек тыща принести Гархладу пища!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Маленьких букашек тыща принести Гархладу пища!',`text_loc8`);
