INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36494,4,1,'Этот кусок сейчас лучше не есть. Глупый Гархлад! ПЛОХОЙ! ПЛОХОЙ!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Этот кусок сейчас лучше не есть. Глупый Гархлад! ПЛОХОЙ! ПЛОХОЙ!',`text_loc8`);
