INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36494,5,0,'%s швыряет в вас глыбой саронита!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s швыряет в вас глыбой саронита!',`text_loc8`);
