INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36497,3,0,'Вихрь погубленных душ взывает к вам!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Вихрь погубленных душ взывает к вам!',`text_loc8`);
