INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36624,1,0,'Я сразу понял, что этот меч был создан драконами.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я сразу понял, что этот меч был создан драконами.',`text_loc8`);
