INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36624,3,0,'Клянусь, Серебряный союз возродит Кель\'Делар!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Клянусь, Серебряный союз возродит Кель\'Делар!',`text_loc8`);
