INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36642,1,0,'Вид клинка и эти отметки указывают на то, что меч был создан драконами. Наконец-то мы получим ответ...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Вид клинка и эти отметки указывают на то, что меч был создан драконами. Наконец-то мы получим ответ...',`text_loc8`);
