INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36642,2,0,'Спустя столько лет... Неужели это...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Спустя столько лет... Неужели это...',`text_loc8`);
