INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36658,0,0,'Его место займет другой. Вы попусту тратите время.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Его место займет другой. Вы попусту тратите время.',`text_loc8`);
