INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36658,11,0,'Иней, уничтожь этого глупца!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Иней, уничтожь этого глупца!',`text_loc8`);
