INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36773,0,1,'%s по дороге в изнеможении роняет кирку на землю.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s по дороге в изнеможении роняет кирку на землю.',`text_loc8`);
