INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36773,0,3,'Жизнью или смертью своей я отплачу тебе за спасение!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Жизнью или смертью своей я отплачу тебе за спасение!',`text_loc8`);
