INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36773,0,4,'Я вернусь ко входу в карьер. Убей парочку мучителей за меня.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я вернусь ко входу в карьер. Убей парочку мучителей за меня.',`text_loc8`);
