INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36794,1,0,'Жалкая букашка! Тебя ждет лишь смерть!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Жалкая букашка! Тебя ждет лишь смерть!',`text_loc8`);
