INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (36794,2,0,'Не думайте, что я так легко позволю вам пройти в покои господина. Сразитесь со мной, если посмеете.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Не думайте, что я так легко позволю вам пройти в покои господина. Сразитесь со мной, если посмеете.',`text_loc8`);
