INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (38805,0,2,'Спасибо тебе – это чуть было не превратилось в резню...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Спасибо тебе – это чуть было не превратилось в резню...',`text_loc8`);
