INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (40083,0,0,'Во вращающихся сферах пульсирует темная энергия!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Во вращающихся сферах пульсирует темная энергия!',`text_loc8`);
