INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (40142,0,0,'Находясь в покое в одном из миров, %s восстанавливает жизненные силы.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Находясь в покое в одном из миров, %s восстанавливает жизненные силы.',`text_loc8`);
