INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (40142,2,0,'Я есть свет и я есть тьма! Трепещите, ничтожные, перед посланником Смертокрыла!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я есть свет и я есть тьма! Трепещите, ничтожные, перед посланником Смертокрыла!',`text_loc8`);
