INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (40301,0,0,'Тигрица-матриарх появляется! Докажите свою силу в бою!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Тигрица-матриарх появляется! Докажите свою силу в бою!',`text_loc8`);
