INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (40991,0,0,'Передай капитану Таррану, что я вернусь в Каранос сразу же, как только удостоверюсь, что бот работает корректно.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Передай капитану Таррану, что я вернусь в Каранос сразу же, как только удостоверюсь, что бот работает корректно.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (40994,0,0,'Мне не терпится попасть туда и присоединиться к битве с этими троллями.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мне не терпится попасть туда и присоединиться к битве с этими троллями.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (41056,0,0,'С тех пор, как произошел катаклизм, мы не переставая воюем. Даже короткая передышка пришлась бы кстати.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','С тех пор, как произошел катаклизм, мы не переставая воюем. Даже короткая передышка пришлась бы кстати.',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (41671,0,1,'Я думал, я умру здесь внизу.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я думал, я умру здесь внизу.',`text_loc8`);
