INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (41671,0,2,'Я думал, они порвут меня на части!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я думал, они порвут меня на части!',`text_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:creature_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_creature_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (41763,0,0,'%s хватает воздух ртом и дрожит от холода.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','%s хватает воздух ртом и дрожит от холода.',`text_loc8`);
