INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52150,0,0,'Нет! НЕЕЕЕТ!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Нет! НЕЕЕЕТ!',`text_loc8`);
