INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52151,1,1,'Пади пред Мандокиром, Повелителем Крови!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Пади пред Мандокиром, Повелителем Крови!',`text_loc8`);
