INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52151,7,0,'Мою кровь примет Хаккар, а мою душу... Джин\'до...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Мою кровь примет Хаккар, а мою душу... Джин\'до...',`text_loc8`);
