INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52155,7,0,'Моя сссссмерть... ничего... не изменит...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Моя сссссмерть... ничего... не изменит...',`text_loc8`);
