INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52156,0,0,'Я свободен! Отомсти за меня!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Я свободен! Отомсти за меня!',`text_loc8`);
