INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52271,1,1,'Засыпайте... увидите еще один сон...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Засыпайте... увидите еще один сон...',`text_loc8`);
