INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52650,0,0,'Живите пока, букашки. Я с вами еще разберусь.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Живите пока, букашки. Я с вами еще разберусь.',`text_loc8`);
