INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52941,2,0,'Давай, покажу тебе кое-что. Где ж я видел эту сумку-то...') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Давай, покажу тебе кое-что. Где ж я видел эту сумку-то...',`text_loc8`);
