INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (52941,3,0,'Прошу. Для разведчика просто самоубийство разгуливать по городу с таким грузом.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Прошу. Для разведчика просто самоубийство разгуливать по городу с таким грузом.',`text_loc8`);
