INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (53565,0,0,'Для новичка твои способности просто поразительны.') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Для новичка твои способности просто поразительны.',`text_loc8`);
