INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (55264,0,6,'За игры и развлечения нужно платить, друзья! Все сюда за жетонами!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','За игры и развлечения нужно платить, друзья! Все сюда за жетонами!',`text_loc8`);
