INSERT INTO `locales_creature_text` (`entry`,`groupid`,`id`,`text_loc8`) VALUES (55402,0,0,'Внимание! Дорогие гости! До начала схватки Новолуния остались считанные секунды! Сундук с призом вот-вот появится в центре арены!') ON DUPLICATE KEY UPDATE `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Внимание! Дорогие гости! До начала схватки Новолуния остались считанные секунды! Сундук с призом вот-вот появится в центре арены!',`text_loc8`);
